package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.manualincident.*;
import cn.mop.domain.manualincident.ManualRecoveryRepository.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class ManualRecoveryControllerTest {
    static final String ACTOR="55000000-0000-4000-8000-000000000001",TENANT="55000000-0000-4000-8000-000000000011",PARENT="55000000-0000-4000-8000-000000000021",ID="55000000-0000-4000-8000-000000000031";
    ObjectMapper mapper=new ObjectMapper();PlatformRepository platform;ManualRecoveryRepository recoveries;ManualRecoveryController controller;
    @BeforeEach void setup(){platform=mock(PlatformRepository.class);recoveries=mock(ManualRecoveryRepository.class);controller=new ManualRecoveryController(platform,recoveries,mapper);role("msp");}
    void role(String value){when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,value,7,true)));}
    Access access(){return new Access(ACTOR,TENANT,7,"synthetic-trace");}
    MockHttpServletRequest request(String method){var r=new MockHttpServletRequest(method,"/api/v1/manual-incidents/"+PARENT+"/recovery");r.setUserPrincipal(()->ACTOR);r.getSession().setAttribute("mop.tenant_id",TENANT);r.setAttribute("mop.trace_id","synthetic-trace");r.addHeader("Idempotency-Key","synthetic-request");return r;}
    ObjectNode input(){return mapper.createObjectNode().put("expected_version",0).put("note","  人工核验😀\n原文\t ").putNull("reported_recovered_at");}
    ManualRecoveryConfirmation value(){return new ManualRecoveryConfirmation(input().get("note").asText(),null);}
    Confirmation confirmation(){return new Confirmation(ID,TENANT,PARENT,ACTOR,value(),Instant.parse("2026-10-03T05:00:00Z"));}
    Map<?,?> data(Object value){return (Map<?,?>)((Map<?,?>)value).get("data");}
    @Test void confirmUsesCurrentScopeAndParentGuardBeforeTransaction(){when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(c->{((Runnable)c.getArgument(6)).run();return ((Supplier<?>)c.getArgument(7)).get();});when(recoveries.confirm(access(),PARENT,0,value())).thenReturn(confirmation());var result=data(controller.write(PARENT,input(),request("POST")));assertEquals(1L,result.get("version"));assertEquals("HUMAN_CONFIRMED",result.get("manual_recovery_status"));Map<?,?> evidence=(Map<?,?>)result.get("confirmation");assertEquals(ACTOR,evidence.get("confirmed_by"));assertEquals(value().note(),evidence.get("note"));assertEquals(value().noteSha256(),evidence.get("note_sha256"));assertNull(evidence.get("reported_recovered_at"));assertNull(evidence.get("monitor_state"));assertNull(evidence.get("disposition_state"));assertEquals(false,evidence.get("ticket_state_changed"));assertEquals(false,evidence.get("sla_changed"));var order=inOrder(recoveries);order.verify(recoveries).authorizeCurrentIncident(access(),PARENT);order.verify(recoveries).confirm(access(),PARENT,0,value());}
    @Test void unknownCurrentIsVersionZeroAndReadNeverCreatesEvidence(){when(recoveries.get(access(),PARENT)).thenReturn(new Current(PARENT,TENANT,0,null));var result=data(controller.get(PARENT,request("GET")));assertEquals(0L,result.get("version"));assertEquals("NOT_CONFIRMED",result.get("manual_recovery_status"));assertNull(result.get("confirmation"));verify(platform,never()).idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any());verify(recoveries,never()).confirm(any(),any(),anyLong(),any());}
    @Test void currentInternalRolesAreExplicitAndCustomersCannotReadOrConfirm(){for(String role:List.of("msp","padmin")){role(role);when(recoveries.get(access(),PARENT)).thenReturn(new Current(PARENT,TENANT,1,confirmation()));assertEquals("HUMAN_CONFIRMED",data(controller.get(PARENT,request("GET"))).get("manual_recovery_status"));assertTrue(Capabilities.forRole(role).contains("manual_recovery:confirm"));}clearInvocations(recoveries);for(String role:List.of("viewer","tadmin","unknown")){role(role);assertEquals(403,assertThrows(DomainException.class,()->controller.get(PARENT,request("GET"))).status);assertEquals(403,assertThrows(DomainException.class,()->controller.write(PARENT,input(),request("POST"))).status);}verifyNoInteractions(recoveries);}
    @Test void invalidOrMissingSessionFailsBeforeReadingParent(){var malformed=request("GET");malformed.getSession().setAttribute("mop.tenant_id",17);assertEquals(401,assertThrows(DomainException.class,()->controller.get(PARENT,malformed)).status);assertEquals(401,assertThrows(DomainException.class,()->controller.get(PARENT,new MockHttpServletRequest())).status);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.empty());assertEquals(401,assertThrows(DomainException.class,()->controller.get(PARENT,request("GET"))).status);verifyNoInteractions(recoveries);}
    @Test void everyInputFieldIsExplicitAndIdentityWorkflowFieldsAreRejected(){for(String field:List.of("expected_version","note","reported_recovered_at")){var body=input();body.remove(field);assertEquals(400,assertThrows(DomainException.class,()->controller.write(PARENT,body,request("POST"))).status);}for(String field:List.of("tenant_id","confirmed_by","recorded_at","monitor_state","disposition_state","ticket_state_changed","sla_changed","manual_recovery_status"))assertEquals(400,assertThrows(DomainException.class,()->controller.write(PARENT,input().put(field,"forged"),request("POST"))).status);verifyNoInteractions(recoveries);}
    @Test void versionTextUnicodeAndTimeAreStrictWithoutDefaults(){for(JsonNode version:List.of(NullNode.instance,TextNode.valueOf("0"),IntNode.valueOf(-1),IntNode.valueOf(2),DoubleNode.valueOf(0.1)))assertEquals(400,assertThrows(DomainException.class,()->controller.write(PARENT,input().set("expected_version",version),request("POST"))).status);for(String text:List.of(" \ufeff\u3000","x\u0085","\ud800","😀".repeat(2001)))assertEquals(400,assertThrows(DomainException.class,()->controller.write(PARENT,input().put("note",text),request("POST"))).status);for(String time:List.of("2026-10-03","2026-10-03T00:00:00.0001Z","0000-01-01T00:00:00Z"))assertEquals(400,assertThrows(DomainException.class,()->controller.write(PARENT,input().put("reported_recovered_at",time),request("POST"))).status);verifyNoInteractions(recoveries);}
    @Test void explicitOffsetIsNormalizedButUnknownTimeRemainsNull(){when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(c->{((Runnable)c.getArgument(6)).run();return ((Supplier<?>)c.getArgument(7)).get();});var known=new ManualRecoveryConfirmation(value().note(),Instant.parse("2020-02-29T00:00:00.123Z"));when(recoveries.confirm(access(),PARENT,0,known)).thenReturn(new Confirmation(ID,TENANT,PARENT,ACTOR,known,Instant.parse("2026-10-03T05:00:00Z")));var result=data(controller.write(PARENT,input().put("reported_recovered_at","2020-02-29T08:00:00.123+08:00"),request("POST")));assertEquals(known.reportedRecoveredAt(),((Map<?,?>)result.get("confirmation")).get("reported_recovered_at"));verify(recoveries).confirm(access(),PARENT,0,known);}
    @Test void strictParserRejectsDuplicateTrailingDepthAndOversizeButAcceptsMaxUnicode()throws Exception{for(String raw:List.of("{\"note\":\"one\",\"note\":\"two\"}","{} {}","[[[1]]]"," ".repeat(32769))){var r=request("POST");r.setContent(raw.getBytes(StandardCharsets.UTF_8));assertEquals(400,assertThrows(DomainException.class,()->ManualRecoveryController.body(r)).status);}var body=input().put("note","😀".repeat(2000));var r=request("POST");r.setContent(mapper.writeValueAsBytes(body));assertEquals(body,ManualRecoveryController.body(r));}
    @Test void cachedOriginalReceiptStillRunsCurrentParentGuardWithoutConfirmingAgain(){when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(c->{((Runnable)c.getArgument(6)).run();return Map.of("original",true);});assertEquals(true,data(controller.write(PARENT,input(),request("POST"))).get("original"));verify(recoveries).authorizeCurrentIncident(access(),PARENT);verify(recoveries,never()).confirm(any(),any(),anyLong(),any());}
    @Test void jsonFieldOrderDoesNotChangeHashButRawNoteAndTimeRemainSignificant(){List<String> hashes=new ArrayList<>();when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(c->{hashes.add(c.getArgument(4));return Map.of("receipt",true);});var original=input();controller.write(PARENT,original,request("POST"));controller.write(PARENT,mapper.createObjectNode().putNull("reported_recovered_at").put("note",value().note()).put("expected_version",0),request("POST"));controller.write(PARENT,input().put("note","changed"),request("POST"));assertEquals(hashes.get(0),hashes.get(1));assertNotEquals(hashes.get(0),hashes.get(2));}
    @Test void noQueryOverridesInvalidParentOrMissingKeyMayReachRepository(){var q=request("GET");q.addParameter("tenant_id",TENANT);assertEquals(400,assertThrows(DomainException.class,()->controller.get(PARENT,q)).status);assertEquals(400,assertThrows(DomainException.class,()->controller.get("bad",request("GET"))).status);for(String key:List.of("","x y","a".repeat(129))){var r=request("POST");r.removeHeader("Idempotency-Key");r.addHeader("Idempotency-Key",key);assertEquals(400,assertThrows(DomainException.class,()->controller.write(PARENT,input(),r)).status);}var missing=request("POST");missing.removeHeader("Idempotency-Key");assertEquals(400,assertThrows(DomainException.class,()->controller.write(PARENT,input(),missing)).status);verifyNoInteractions(recoveries);}
}
